/**
 * Item catalog for the Loot search feature — scraped from
 * https://miracle74.com/?subtopic=items (Tibia 7.4 OT server "Miracle").
 *
 * `sourceId` is the item id used by that site (`?subtopic=items&id=<id>`),
 * kept so this file can be re-scraped/extended later without duplicating
 * entries. Categories with 100% NPC "sell to" coverage as of this scrape:
 * Axes, Swords, Clubs, Distance, Ammunition, Shields, Helmets, Armors.
 * Legs/Boots/Amulets/Rings/Valuables/Relics have name+weight for every item,
 * but only a sample has `npcPrices` filled in — re-run the same scraping
 * pass (see README) to fill in the rest.
 */

export interface ItemNpcPriceSeed {
  npc: string;
  city?: string;
  price: number;
}

export interface ItemSeed {
  sourceId: number;
  name: string;
  category: string;
  weight?: number;
  attack?: number;
  defense?: number;
  npcPrices?: ItemNpcPriceSeed[];
}

function sell(...rows: [string, string | undefined, number][]): ItemNpcPriceSeed[] {
  return rows.map(([npc, city, price]) => ({ npc, city, price }));
}

